import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`amazon-listing-rewrite`,heroTitle:`Audit and rewrite your Amazon listing in minutes`,heroSubtitle:`Perplexity Computer audits your Amazon listing against search winners, rewrites the copy, and delivers an A9-ready optimization plan automatically.`,inputUrlCta:`Rewrite my listing`,inputUrlPlaceholder:`ASIN or amazon.com/dp/...`,inputUrlPrefill:`Use {url} as the Amazon product listing to audit. Extract the current title, bullet points, description, images, and A+ content. Research the top ranking competitors for the primary keywords this product should win on. Then rewrite the listing with a stronger title, bullet points, product description, backend keyword ideas, image recommendations, and A+ content suggestions. Include a gap analysis that explains what competitors are doing better and a prioritized action plan for improving rank and conversion.`,heroOverlaySteps:[`Pulling your title, bullets, description, images, and A+ content`,`Benchmarking top competitors for keyword coverage and conversion hooks`,`Rewriting the listing for stronger search visibility and sales copy`,`Updated listing copy, keyword gaps, and next steps ready to implement`],generatingSteps:[`Opening {url} to capture your current listing copy and merchandising assets`,`Designing an agent to benchmark keyword leaders and adjacent competitors`,`Configuring title, bullet, description, and A+ content rewrites for Amazon SEO`,`Preparing your optimization report with before-and-after copy and fix priorities`],featureSectionTitle:`From stale listing to ranked product page`,featureCardTitles:[`Connects to your ecommerce stack`,`Outputs ready to publish`],featureCardDescriptions:[`Computer breaks your listing rewrite into research, keyword analysis, conversion copywriting, and merchandising tasks, then routes each step to the model best suited for it.`,`Amazon, Google Sheets, Notion, and Drive plug into one workflow so audits, rewrites, and implementation notes stay organized.`,`Rewritten titles, bullets, descriptions, keyword targets, and A+ recommendations come back structured so your team can update the listing immediately.`],capabilitySectionTitle:`Your Amazon optimization analyst, on demand`,capabilitySectionSubtitle:`Paste an ASIN or listing URL, then come back to a rewritten page and a ranking plan.`,capabilityCards:[{title:`Listing Audit`,description:`Computer can inspect your current title, bullets, description, images, and merchandising structure to flag weak positioning and missing buyer signals.`},{title:`Competitor Benchmarking`,description:`Computer can study top-ranking competitor listings to extract keyword coverage, pricing cues, merchandising patterns, and conversion hooks.`},{title:`Copy Rewrites`,description:`Computer can rewrite the full listing with stronger keyword placement, clearer benefit framing, and more persuasive bullet points and descriptions.`},{title:`Connect Your Tools`,description:`Computer can send rewrites and audit notes into Sheets, Notion, and Drive so your catalog workflow stays centralized.`},{title:`Remember & Learn`,description:`Computer can remember your catalog, brand voice, and category priorities so future listing rewrites get sharper over time.`},{title:`Monitor Ranking Gaps`,description:`Computer can revisit competitor listings and keyword positioning on a schedule so you know when your page needs another refresh.`}]});export{t as default};
